import 'dart:convert';import 'package:battery_plus/battery_plus.dart';import 'package:http/http.dart'as http;import 'package:sheshield/config/api_config.dart';import 'package:sheshield/services/auth_service.dart';import 'package:sheshield/services/location_service.dart';
class GuardianStatus{const GuardianStatus({required this.studentName,required this.studentEmail,required this.emergencyStatus,this.emergencyId,this.latitude,this.longitude,this.sosTime,this.battery,this.lastUpdated});final String studentName,studentEmail,emergencyStatus;final int?emergencyId,battery;final double?latitude,longitude;final DateTime?sosTime,lastUpdated;factory GuardianStatus.fromJson(Map<String,dynamic>j)=>GuardianStatus(studentName:j['studentName'].toString(),studentEmail:j['studentEmail'].toString(),emergencyStatus:j['emergencyStatus'].toString(),emergencyId:(j['emergencyId']as num?)?.toInt(),latitude:(j['latitude']as num?)?.toDouble(),longitude:(j['longitude']as num?)?.toDouble(),sosTime:j['sosTime']==null?null:DateTime.parse(j['sosTime']),battery:(j['battery']as num?)?.toInt(),lastUpdated:j['lastUpdated']==null?null:DateTime.parse(j['lastUpdated']));}
class GuardianService{Future<Map<String,dynamic>>_request(String method,String path,{Map<String,dynamic>?body,bool auth=true})async{final token=auth?await AuthService().readToken():null;final headers={'Content-Type':'application/json',if(token!=null)'Authorization':'Bearer $token'};final uri=ApiConfig.endpoint(path);final r=method=='GET'?await http.get(uri,headers:headers):await http.post(uri,headers:headers,body:jsonEncode(body));final data=r.body.isEmpty?<String,dynamic>{}:jsonDecode(r.body)as Map<String,dynamic>;if(r.statusCode<200||r.statusCode>=300)throw AuthException(data['message']?.toString()??'Guardian request failed.');return data;}Future<Map<String,dynamic>>pairing(int id)=>_request('POST','/api/guardian/pairing/$id');Future<String>login(String email,String code)async=>(await _request('POST','/api/guardian/login',body:{'studentEmail':email,'pairingCode':code},auth:false))['guardianToken'].toString();Future<GuardianStatus>status(String token)async=>GuardianStatus.fromJson(await _request('GET','/api/guardian/status?token=${Uri.encodeQueryComponent(token)}',auth:false));Future<void>sync(int userId)async{try{final battery=await Battery().batteryLevel;final p=await LocationService().getCurrentPosition();final jwt=await AuthService().readToken();await http.put(ApiConfig.endpoint('/api/guardian/device-status'),headers:{'Content-Type':'application/json','Authorization':'Bearer $jwt'},body:jsonEncode({'userId':userId,'battery':battery,'latitude':p.latitude,'longitude':p.longitude}));}catch(_){}}
}
